"""Build the RAIMAL identity reference and portable design tokens."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
COLORS = {
    'field': '#5A9367', 'grove': '#44633F', 'earth': '#3F4B3B',
    'ink': '#263329', 'chalk': '#F6F7F2', 'white': '#FFFFFF',
    'mist': '#E7EDE2', 'line': '#CBD5C5', 'muted': '#596653',
    'water': '#245C73', 'caution': '#805411', 'caution-bg': '#FFF1D6',
    'critical': '#A13932', 'critical-bg': '#FBEAE6',
}

def luminance(h):
    rgb = [int(h[i:i+2],16)/255 for i in (1,3,5)]
    return sum(v*w for v,w in zip([v/12.92 if v <= .04045 else ((v+.055)/1.055)**2.4 for v in rgb], [.2126,.7152,.0722]))

def contrast(a,b):
    a,b=sorted([luminance(COLORS[a]), luminance(COLORS[b])])
    return (b+.05)/(a+.05)

pairs = [('ink','chalk'), ('earth','white'), ('grove','white'), ('muted','chalk'), ('white','grove'), ('water','white'), ('caution','caution-bg'), ('critical','critical-bg'), ('field','white')]
report = [{'foreground':a,'background':b,'ratio':round(contrast(a,b),2),'normal_text_AA':contrast(a,b)>=4.5} for a,b in pairs]
(ROOT/'contrast-report.json').write_text(json.dumps(report,indent=2)+'\n')
tokens = {'color':{k:{'$type':'color','$value':v} for k,v in COLORS.items()},
          'font':{'sans':{'$type':'fontFamily','$value':['Segoe UI','Arial','sans-serif']},'mono':{'$type':'fontFamily','$value':['Consolas','monospace']}},
          'spacing':{str(v):{'$type':'dimension','$value':{'value':v,'unit':'px'}} for v in (4,8,12,16,24,32,48,64,96)},
          'radius':{'control':{'$type':'dimension','$value':{'value':8,'unit':'px'}},'panel':{'$type':'dimension','$value':{'value':16,'unit':'px'}}}}
(ROOT/'raimal.tokens.json').write_text(json.dumps(tokens,indent=2)+'\n')
css='/* RAIMAL identity v1.0 | Reference tokens; importing does not restyle components. */\n:root {\n'
css+=''.join(f'  --raimal-{k}: {v};\n' for k,v in COLORS.items())
css+='  --raimal-font-sans: "Segoe UI", Arial, sans-serif;\n  --raimal-font-mono: Consolas, monospace;\n'
css+=''.join(f'  --raimal-space-{v}: {v}px;\n' for v in (4,8,12,16,24,32,48,64,96))
css+='  --raimal-radius-control: 8px;\n  --raimal-radius-panel: 16px;\n  --raimal-focus: 0 0 0 3px #FFFFFF, 0 0 0 6px #245C73;\n}\n'
(ROOT/'raimal.tokens.css').write_text(css)

swatches=''.join(f'<article class="swatch" style="--swatch:{COLORS[k]}"><div></div><h3>{name}</h3><code>{COLORS[k]}</code><p>{role}</p></article>' for k,name,role in [
    ('field','Field','Recognition · illustration'),('grove','Grove','Actions · emphasis'),('earth','Earth','Wordmark · headings'),('chalk','Chalk','Primary canvas'),('mist','Mist','Quiet surfaces'),('ink','Ink','Body copy · data')])
rows=''.join(f'<tr><td>{a.title()} / {b.title()}</td><td>{contrast(a,b):.2f}:1</td><td>{"Normal text" if contrast(a,b)>=4.5 else "Large text / graphics only"}</td></tr>' for a,b in pairs)
html='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RAIMAL — Brand identity</title>
<link rel="stylesheet" href="raimal.tokens.css"><style>
*{box-sizing:border-box}body{margin:0;background:var(--raimal-chalk);color:var(--raimal-ink);font:16px/1.6 var(--raimal-font-sans)}
main{max-width:1440px;margin:auto}section{padding:72px 80px;border-bottom:1px solid var(--raimal-line)}
.eyebrow,.label{font:12px/1.4 var(--raimal-font-mono);letter-spacing:.15em;text-transform:uppercase}.eyebrow{color:var(--raimal-grove)}
h1,h2,h3,p{margin:0}h1{font-size:clamp(48px,6.2vw,88px);line-height:1.02;letter-spacing:-.055em;font-weight:600;margin:28px 0}h2{font-size:40px;line-height:1.12;letter-spacing:-.035em;font-weight:600;margin:16px 0 24px}h3{font-size:18px;font-weight:600}p{max-width:650px}.sub{font-size:19px;color:var(--raimal-muted)}.topline{display:flex;justify-content:space-between;gap:20px}.hero{display:grid;grid-template-columns:1.05fr 1fr;gap:64px;align-items:center;min-height:650px}.logo-panel{background:white;border:1px solid var(--raimal-line);border-radius:50% 50% 16px 16px;padding:36px;position:relative}.logo-panel img{width:100%;display:block}.logo-panel .label{text-align:center;color:var(--raimal-muted);margin-top:-28px;padding-bottom:20px}.hero-note{margin-top:36px;padding-top:20px;border-top:1px solid var(--raimal-line);font-size:13px;color:var(--raimal-muted)}
.split{display:grid;grid-template-columns:1fr 1.25fr;gap:72px}.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:40px}.principles article{border-top:2px solid var(--raimal-grove);padding-top:16px}.principles p{font-size:14px;color:var(--raimal-muted);margin-top:8px}.swatches{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin-top:32px}.swatch>div{height:150px;border-radius:12px;background:var(--swatch);border:1px solid #26332914}.swatch h3{margin-top:16px}.swatch code{font-size:13px}.swatch p{font-size:12px;color:var(--raimal-muted);margin-top:8px}.ratio{height:18px;display:flex;border-radius:12px;overflow:hidden;margin:36px 0 12px}.ratio span:nth-child(1){width:60%;background:var(--raimal-mist)}.ratio span:nth-child(2){width:25%;background:var(--raimal-earth)}.ratio span:nth-child(3){width:10%;background:var(--raimal-field)}.ratio span:nth-child(4){width:5%;background:var(--raimal-water)}.small{font-size:13px;color:var(--raimal-muted)}
.type-sample{font-size:64px;line-height:1.1;letter-spacing:-.045em;margin:20px 0}.type-line{padding:18px 0;border-bottom:1px solid var(--raimal-line);display:flex;justify-content:space-between;gap:20px}.mono{font-family:var(--raimal-font-mono)}.type-line span:last-child{font-size:12px;color:var(--raimal-muted)}
.dark{background:var(--raimal-earth);color:var(--raimal-chalk)}.dark .eyebrow,.dark .small{color:var(--raimal-mist)}.pattern{width:100%;height:260px}.logo-rules{display:grid;grid-template-columns:1fr 1fr;gap:32px}.logo-stage{padding:24px 60px;background:white;border:1px solid var(--raimal-line);border-radius:16px}.logo-stage img{display:block;width:100%;max-width:280px;margin:auto;outline:1px dashed var(--raimal-line)}.rules p{margin:0 0 16px}.rules strong{display:block}.mock{margin-top:40px;background:white;border:1px solid var(--raimal-line);border-radius:16px;overflow:hidden}.mock-header{display:flex;align-items:center;justify-content:space-between;padding:24px 32px;border-bottom:1px solid var(--raimal-line)}.mock-header img{width:180px;height:110px;object-fit:contain}.mock-brand{display:flex;align-items:center;gap:24px}.badge{border-radius:20px;padding:6px 12px;background:var(--raimal-mist);font:12px var(--raimal-font-mono)}.mock-body{display:grid;grid-template-columns:1fr 1fr;gap:48px;padding:40px}.field-illustration{background:var(--raimal-chalk);border-radius:12px;display:grid;place-items:center;min-height:270px}.field-illustration svg{width:230px;height:230px}.status{color:var(--raimal-caution);background:var(--raimal-caution-bg);display:inline-block;padding:6px 12px;border-radius:6px;font-size:13px}.button{display:inline-block;background:var(--raimal-grove);color:white;padding:12px 20px;border-radius:8px;font-weight:600;margin-top:24px}.mock h3{font-size:30px;line-height:1.15;letter-spacing:-.02em;margin:20px 0 12px}.mock p{font-size:14px;color:var(--raimal-muted)}.mock footer{padding:16px 32px;border-top:1px solid var(--raimal-line);font-size:12px;color:var(--raimal-muted)}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid var(--raimal-line);padding:10px 8px}th{font-weight:600}.semantic{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.semantic span{padding:7px 12px;border-radius:6px;font-size:13px}.foot{padding:24px 80px;display:flex;justify-content:space-between;font-size:12px;color:var(--raimal-muted)}
@media(max-width:800px){section{padding:40px 24px}.hero,.split,.logo-rules,.mock-body{grid-template-columns:1fr;gap:32px}.hero{min-height:0}.logo-panel{max-width:420px;margin:auto}.swatches{grid-template-columns:repeat(3,1fr)}.principles{grid-template-columns:1fr}.swatch>div{height:100px}.type-sample{font-size:46px}.mock-header,.mock-body{padding:20px}.foot{padding:24px;gap:20px}h2{font-size:32px}.topline{font-size:10px}.mock-brand{gap:12px}.mock-header{flex-wrap:wrap;gap:16px}.mock-brand{flex-wrap:wrap}}
</style></head><body><main>
<section><div class="topline label"><span>RAIMAL / Identity system</span><span>01 — Brand foundations · v1.0</span></div><div class="hero"><div><div class="eyebrow">Rooted in the field. Built for clarity.</div><h1>Read the field.<br>Focus the<br>next check.</h1><p class="sub">A grounded, precise identity for agricultural intelligence — shaped by the circular field at the heart of the RAIMAL mark.</p><p class="hero-note">RAIMAL brings field observations into a focused inspection workflow.<br>Brand direction · Color system · Typography · Applications</p></div><div class="logo-panel"><img src="RAIMAL-logo-final.png" alt="RAIMAL approved logo: curved green field bands above a geometric wordmark"><div class="label">The field is our starting point.</div></div></div></section>
<section><div class="split"><div><div class="eyebrow">01 / Character</div><h2>Calm confidence.<br>Practical intelligence.</h2></div><p class="sub">RAIMAL connects field observations with a clear next step. The identity pairs organic field geometry with disciplined layouts: natural in color, technical in detail, and direct in language.</p></div><div class="principles"><article><h3>Grounded</h3><p>Muted greens, warm open space, and a visible connection to cultivated land.</p></article><article><h3>Precise</h3><p>Aligned grids, clear hierarchy, tabular data, and purposeful diagrams.</p></article><article><h3>Actionable</h3><p>Lead with what to inspect. Separate observed patterns from confirmed findings.</p></article></div></section>
<section><div class="eyebrow">02 / Color</div><h2>Three greens. One coherent system.</h2><p class="sub">The approved logo palette anchors the identity. Supporting neutrals give it space; functional colors carry specific meanings.</p><div class="swatches">SWATCHES</div><div class="ratio" aria-label="Suggested composition: 60 percent light neutrals, 25 percent dark tones, 10 percent field green, 5 percent functional accents"><span></span><span></span><span></span><span></span></div><p class="small">Suggested composition: 60% light neutrals · 25% dark tones · 10% Field · up to 5% functional accents. Use less accent color on data-heavy screens.</p></section>
<section><div class="split"><div><div class="eyebrow">03 / Typography</div><h2>Open. Legible.<br>Uncomplicated.</h2><p class="sub">Segoe UI provides a practical humanist counterpoint to the angular logo. Keep the custom wordmark exclusive to the logo.</p><p class="small" style="margin-top:24px">Use Arial, then sans-serif as fallbacks. Use Consolas for identifiers and technical labels. No remote font dependency.</p></div><div><div class="label">Segoe UI / Regular + Semibold</div><div class="type-sample">A clearer view<br>of every field.</div><div class="type-line"><strong>Display / 64–88</strong><span>1.05 line height · −0.04em</span></div><div class="type-line"><strong>Heading / 32–40</strong><span>1.15 line height · −0.025em</span></div><div class="type-line"><span>Body / 16–18</span><span>1.6 line height · normal tracking</span></div><div class="type-line mono"><span>FIELD 07 / SECTOR 03</span><span>Label / 12–13</span></div></div></div></section>
<section class="dark"><div class="split"><div><div class="eyebrow">04 / Graphic language</div><h2>Field curves.<br>Structured space.</h2><p>Broad arcs echo the cultivated rows in the mark. Use them as quiet framing devices on covers and section dividers.</p><p class="small" style="margin-top:24px">Rounded panels: 16px · Controls: 8px<br>Spacing: 4 / 8 / 12 / 16 / 24 / 32 / 48 / 64 / 96px<br>Decorative artwork below; not a logo or measured field.</p></div><svg class="pattern" viewBox="0 0 520 260" aria-label="Decorative field arcs" role="img"><defs><clipPath id="crop"><rect width="520" height="260" rx="16"/></clipPath></defs><g clip-path="url(#crop)" fill="none" stroke="#5A9367" stroke-width="36"><path d="M-50 210 Q180 -80 590 90"/><path d="M-50 274 Q180 -16 590 154"/><path d="M-50 338 Q180 48 590 218"/><path d="M-50 402 Q180 112 590 282"/></g></svg></div></section>
<section><div class="eyebrow">05 / Logo use</div><h2>Give the mark room to work.</h2><div class="logo-rules"><div class="logo-stage"><img src="RAIMAL-logo-final.png" alt="Unmodified approved RAIMAL logo on white"></div><div class="rules"><p><strong>Use the approved asset intact.</strong>Preserve its colors, proportions, symbol, and lettering. Place it on white or Chalk.</p><p><strong>Protect the surrounding space.</strong>Leave at least one wordmark-letter height around the visible logo. The supplied PNG already includes generous transparent margins.</p><p><strong>Minimum starting size.</strong>Use a 180px-wide image box digitally, or 40mm in print. Check the wordmark at the final output size.</p><p><strong>Use a light plate on dark backgrounds.</strong>Do not recolor, stretch, add effects, or set the dark wordmark directly on Earth. A compact icon and reversed logo require separate approved assets.</p></div></div></section>
<section><div class="eyebrow">06 / Application specimen</div><h2>From identity to inspection.</h2><p class="sub">A quiet workspace, a visible evidence label, and one clear next action.</p><div class="mock"><div class="mock-header"><div class="mock-brand"><img src="RAIMAL-logo-final.png" alt="RAIMAL"><strong>RAIMAL</strong></div><span class="badge">DEMO DATA</span></div><div class="mock-body"><div class="field-illustration"><svg viewBox="0 0 240 240" role="img" aria-label="Illustrative circular field with a highlighted inspection sector"><circle cx="120" cy="120" r="104" fill="#E7EDE2"/><g fill="none" stroke="#5A9367" stroke-width="1.5"><circle cx="120" cy="120" r="84"/><circle cx="120" cy="120" r="62"/><circle cx="120" cy="120" r="40"/><path d="M120 16V224M16 120H224"/></g><path d="M120 120L210 68A104 104 0 0 1 224 120Z" fill="#FFF1D6" stroke="#805411" stroke-width="2"/><circle cx="120" cy="120" r="5" fill="#3F4B3B"/></svg></div><div><span class="status">△ Needs inspection</span><h3>Review the eastern sector.</h3><p>This synthetic example shows a persistent crop-pattern change. Check the field before attributing it to an irrigation fault.</p><div class="type-line mono"><span>FIELD 07</span><span>Illustrative sample</span></div><span class="button">Review evidence →</span><p class="small" style="margin-top:12px">Visual component specimen · non-interactive</p></div></div><footer>Illustrative field graphic and sample copy. No live monitoring or validated fault detection is implied.</footer></div></section>
<section><div class="split"><div><div class="eyebrow">07 / Accessible color</div><h2>Color supports<br>the message.</h2><p>Use Grove for filled actions with white labels. Field green is an identity and graphic color; its contrast on white is too low for normal-size text.</p><div class="semantic"><span style="background:#E7EDE2;color:#44633F">✓ Recorded</span><span style="background:#FFF1D6;color:#805411">△ Needs inspection</span><span style="background:#FBEAE6;color:#A13932">! Confirmed issue</span><span style="background:white;color:#245C73">i Information</span></div><p class="small" style="margin-top:24px">Always pair statuses with a label or icon. “Confirmed issue” requires a recorded field finding. Normal text target: 4.5:1; large text and essential graphics: 3:1. Ratios shown for solid color pairs.</p></div><div><table><thead><tr><th>Foreground / background</th><th>Contrast</th><th>Use</th></tr></thead><tbody>ROWS</tbody></table></div></div></section>
<div class="foot"><span>RAIMAL / Brand identity v1.0</span><span>8 October 2026 · Based on the approved logo</span></div>
</main></body></html>'''.replace('SWATCHES',swatches).replace('ROWS',rows)
(ROOT/'RAIMAL-brand-identity.html').write_text(html,encoding='utf-8')
print('Built identity guide, CSS and JSON tokens, and contrast report.')
print(json.dumps(report,indent=2))
